<template>
    <div class="login">
      <el-container>
        <el-header height="80px">
          <el-row type="flex" justify="space-between">
            <el-col class="logo" :span="6">
              <a href="https://hf.pigcms.com" v-bind:style="{ backgroundImage: 'url('+ config.site_logo +')', }"></a>
              <span>店员登录</span>
            </el-col>
            <el-col class="qcode-btn" :span="3">
              <el-button type="primary" size="mini" @click="dialogVisible = true">移动端下载</el-button>
            </el-col>
          </el-row>
        </el-header>
        <el-main >
          <el-row class="form-wrapper"  type="flex" justify="center" align="middle">
            <el-col>
              <el-form  :model="form"  >
                <div class="title">欢迎登录</div>
                <el-form-item  prop="account">
                  <el-input v-model="form.account" placeholder="账号/手机号">
                    <template slot="prepend"><i class="el-icon-user"></i></template>
                  </el-input>
                </el-form-item>
                <el-form-item  prop="pass">
                  <el-input v-model="form.passwd" placeholder="密码" show-password>
                    <template slot="prepend"><i class="el-icon-lock"></i></template>
                  </el-input>
                </el-form-item>
                <el-form-item class="submit-btn-wrapper">
                  <el-button  type="primary" @click="onSubmit" @keyup.enter.native="onSubmit">登录</el-button>
                </el-form-item>
              </el-form>
            </el-col>
          </el-row>
          <div class="rightAside">
            <a :href="'http://wpa.qq.com/msgrd?v=3&uin=' + config.site_qq + '&site=qq&menu=yes'" target="_blank" class="qqCounsel pointer">
              <div class="block block1 on">
                <i class="icon iconfont">&#xe605;</i>
                <p>在线咨询</p>
              </div>
            </a>
            <div class="block block2">
              <i class="iconfont icon">&#xe600;</i>
              <p>关注我们</p>
              <div class="qrcode">
                <div class="qrcodeWrap">
                  <img :src="config.wechat_qrcode" alt="公众号二维码">
                  <p>扫码关注</p>
                </div>
              </div>
            </div>
            <div class="block block3">
              <i class="iconfont icon">&#xe676;</i>
              <p>联系电话</p>
              <div class="qrcode phone">
                <div class="qrcodeWrap">
                  <p>{{config.site_phone}}</p>
                </div>
              </div>
            </div>
            <div class="block block4">
              <i class="iconfont icon">&#xe61c;</i>
              <p>联系邮箱</p>
              <div class="qrcode email">
                <div class="qrcodeWrap">
                  <p>{{config.site_email}}</p>
                </div>
              </div>
            </div>
          </div>
          <el-dialog
            title="下载移动端，随时随地管理店铺"
            :visible.sync="dialogVisible"
            width="35%" :show-close="false" center top="36vh">
            <el-row type="flex" justify="center">
              <el-col :span="12">
                <div><img :src="config.h5_qrcode_url" alt=""></div>
                <div>微信扫一扫</div>
              </el-col>
              <el-col :span="12" v-if="config.app_qrcode_url != '' ">
                <div><img :src="config.app_qrcode_url" alt=""></div>
                <div>扫码下载APP</div>
              </el-col>
            </el-row>
          </el-dialog>
        </el-main>
        <el-footer v-html="config.footer_copyright"></el-footer>
      </el-container>
    </div>
</template>

<script>
export default {
  name: 'Login',
  data () {
    return {
      form: {
        account: '',
        passwd: ''
      },
      config: this._global.config,
      dialogVisible: false
    }
  },
  created () {
    this.getConfig()
  },
  components: {
  },

  methods: {
    isLogin () {
      if (this._util.getCache('ticket')) {
        this.$router.push({ path: '/home' })
      }
    },
    // 提交账号、密码
    async onSubmit () {
      if (!this.form.account) {
        this.$message.error('请输入账号信息哦')
        return
      }
      if (!this.form.passwd) {
        this.$message.error('请输入密码哦')
        return
      }
      try {
        let res = await this.$api.checkLogin(this.form)
        if (res.errorMsg) {
          this.$message.error(res.errorMsg)
        } else {
          this._util.setCache('ticket', res.ticket)
          this._util.setCache('store_staff', res.user)
          this._global.storeInfo = res.user
          this._global.ticket = res.ticket
          this.$router.replace({ path: '/home' })
        }
      } catch (e) {
        console.log('登录错误', e)
      }
    },
    // 获取config
    async getConfig () {
      // 这里用try catch包裹，请求失败的时候就执行catch里的
      try {
        let res = await this.$api.getConfig()
        this._global.config = this.config = res
        this._util.setCache('store_config', res)
        console.log('2222', this.config, this._global.config)
      } catch (e) {
        console.log('获取config错误', e)
      }
      this.isLogin()
    }
  }
}
</script>

<style lang="stylus" rel="stylesheet/stylus" scoped>
  .login{
    height 100%
    overflow hidden
  }

  .login .el-header, .login .el-footer{
    color: #333;
    text-align: center;
    line-height: 80px;
    height:80px;
  }

  .login .el-footer, .login .el-footer a{
    color:#999
  }

  .login .el-header{
    background:#fff;
    box-shadow: 0 2px 4px rgba(0, 0, 0, .12), 0 0 6px rgba(0, 0, 0, .04)
  }

  .login .el-main {
    color: #333;
    height:100%;
  }

  .login .el-container {
    height:100%;
    min-width:500px;
    background: #f3f3f3 url(images/login_bg.png) top left no-repeat;
  }

  .login .el-row {
    /*margin-bottom: 20px;*/
    &:last-child {
      margin-bottom: 0;
    }
  }
  .login .el-col {
    border-radius: 4px;
  }

  .login .logo{
    white-space:nowrap;
  }

  .login .logo a{
    background: url('') no-repeat;
    display: inline-block;
    width: 160px;
    height: 50px;
    background-size: contain;
    vertical-align: middle;
    margin-right:10px;
  }

  .login .logo span{
    position:relative;
    padding-left:30px;
    font-size:16px;
    color:#666;
  }

  .login .logo span::before{
    content: "";
    position: absolute;
    display: block;
    width: 1px;
    height: 26px;
    top: -2px;
    background: #dedede;
    left: 5px;
  }

  .login .form-wrapper{
    height:100%;
  }

  .form-wrapper .el-col{
    width:380px;
  }

  .el-form{
    background:#fff;
    padding:30px;
    padding-bottom:15px;
    border-radius:8px;
  }
  .el-form .title{
    font-size:16px;
    color:#999;
    text-align center;
    padding-bottom:25px;
    letter-spacing:5px;
  }

  .el-form i{
    font-size:18px;
  }

  .submit-btn-wrapper .el-button{
    width:100%;

  }

  .rightAside {
    width: 80px;
    font-size: 12px;
    color: #666;
    position: fixed;
    bottom: 100px;
    right: 20px;
  }
  .pointer {
    cursor: pointer;
  }
  .rightAside .block {
    width: 80px;
    height: 78px;
    text-align: center;
    line-height: 24px;
    box-sizing: border-box;
    padding-top: 16px;
    position: relative;
    cursor: pointer;
    background: #fff;
    box-shadow: 0 0 30px rgba(0,0,0,.3);
  }
  .rightAside .block.on {
    background: #00bf5a;
    color: #fff;
  }
  .rightAside .block i {
    font-size: 22px;
  }
  .rightAside .block1 {
    animation: rotateInDownLeft 1s 0s 1 linear both;
  }
  .rightAside .block2 {
    animation: rotateInDownRight 1s .3s 1 linear both;
  }
  .rightAside .block3 {
    animation: rotateInDownLeft 1s .6s 1 linear both;
  }
  .rightAside .block4 {
    animation: rotateInDownRight 1s .9s 1 linear both;
  }
  .rightAside .block:hover {
    background:   #00bf5a;
    color: #fff;
  }
  .rightAside .block .qrcode {
    width: 170px;
    height: 190px;
    font-size: 16px;
    position: absolute;
    right: 79px;
    top: -56px;
    display: none;
  }
  .rightAside .block:hover .qrcode {
    display: block;
  }
  .rightAside .block .qrcode .qrcodeWrap {
    width: 120px;
    background: #fff;
    box-shadow: 0 0 30px rgba(0,0,0,.3);
    height: 150px;
    padding: 20px;
  }
  .rightAside .block:hover .qrcode p {
    color: #333;
  }
  .rightAside .block .qrcode img {
    width: 120px;
    height: 120px;
    margin-bottom: 10px;
  }
  .rightAside .block .qrcode:before{content:"";width:0;height:0;border:8px solid transparent;border-left-color:#fff;position:absolute;top:46%;right:-6px}

  .rightAside .block .qrcode.phone,.rightAside .block .qrcode.email{
    height:100px;
    top:-20px;
  }
  .rightAside .block .qrcode.phone .qrcodeWrap,.rightAside .block .qrcode.email .qrcodeWrap{
    height:80px;
    line-height:80px;
  }
  .rightAside .block .qrcode.email{
    font-size:12px;
  }

  .el-dialog img{
    width:80%;
    margin-bottom 5px;
  }

  .el-dialog .el-col{
    text-align center
  }

</style>
